     <div id="WE199a7120fd" class="BaseDiv RKeepRatio OEWEImage OESK_WEImage_Default" style="z-index:1008" data-ot="Lame de la pyramide" data-ot-delay="0.2" data-ot-target="true" data-ot-target-joint="top right" data-ot-tip-joint="bottom left">
